declare(strict_types=1);namespace BSPCompare;require __DIR__.'/model.php';$ok=0;$bad=0;function test($name,$fn){global $ok,$bad;try{$fn();$ok++;echo "PASS $name\n";}catch(\Throwable $e){$bad++;echo "FAIL $name: {$e->getMessage()}\n";}}function check($v){if(!$v)throw new \RuntimeException('Assertion failed');}function near($a,$b,$tol=1e-10){check(abs($a-$b)<=$tol*max(1,abs($b)));}function rejects($p){try{evaluate($p);}catch(\InvalidArgumentException $e){return;}throw new \RuntimeException('Invalid input accepted');}
foreach(presets() as $id=>$s){test('preset '.$id,function()use($id){$p=preset($id);$r=evaluate($p);check(count($r['rows'])===$p['samples']);near($r['rows'][0]['x'],$p['start']);near($r['rows'][count($r['rows'])-1]['x'],$p['end']);foreach($r['rows'] as $row)near($row['delta'],$row['candidate']-$row['reference']);check($r===evaluate($r['plan']));});}
foreach(catalog()['models'] as $id=>$m){foreach($m['params'] as $s)test('all-model sweep '.$id.' '.$s['key'],function()use($id,$m,$s){$p=['schema'=>SCHEMA,'model'=>$id,'parameter'=>$s['key'],'start'=>$s['min'],'end'=>$s['max'],'samples'=>3,'metric'=>$m['numeric_metrics'][0]['label']];$r=evaluate($p);foreach($r['rows'] as $row){near($row['delta'],0);$params=$r['plan']['candidate'];$params[$s['key']]=$row['x'];near($row['candidate'],numeric_metric(run_model($id,$params),$p['metric'])['value']);}});}
test('massless group speed stays unity',function(){foreach(evaluate(preset('light'))['rows'] as $r)near($r['reference'],1);});test('clock pair exact rest and speed response',function(){$r=evaluate(preset('clocks'));near($r['rows'][0]['reference'],10);near($r['rows'][0]['candidate'],8);near($r['rows'][20]['reference'],10*sqrt(1-.99*.99));});test('escape fixed comparator unchanged',function(){$r=evaluate(preset('escape'));foreach($r['rows'] as $row)near($row['reference'],sin(12)**2);});test('wall illustrative conflict',function(){$p=preset('wall');$p['probe']=1.2;$r=evaluate($p);near($r['probe']['center']['delta'],19.89974874213239-3.2834546816744044);});test('distance signed bias',function(){$r=evaluate(preset('distance'));check($r['rows'][0]['delta']<0&&$r['rows'][20]['delta']>0);});test('anchor zero reference',function(){foreach(evaluate(preset('anchors'))['rows'] as $r)near($r['reference'],0);});test('zero probe width yields null slope',function(){$p=preset('light');$p['half_width']=0;check(evaluate($p)['probe']['secant_slopes']['delta']===null);});test('clipped probe',function(){$p=preset('light');$p['probe']=0;$p['half_width']=1;$r=evaluate($p);check($r['probe']['clipped']);near($r['probe']['lower']['x'],0);near($r['probe']['upper']['x'],1);});test('max samples',function(){$p=preset('light');$p['samples']=65;check(count(evaluate($p)['rows'])===65);});foreach(['schema'=>'wrong','model'=>'unknown','parameter'=>'unknown','start'=>-1,'end'=>100,'samples'=>66,'metric'=>'not a metric','reference_metric'=>'Transferred energy','reference_mode'=>'wrong','probe'=>100,'half_width'=>-1,'candidate'=>['gap'=>1],'reference'=>['x'=>0],'fake_results'=>[]] as $k=>$v)test('reject '.$k,function()use($k,$v){$p=preset('light');$p[$k]=$v;rejects($p);});test('reject descending range',function(){$p=preset('light');$p['start']=2;rejects($p);});test('reject paired metric unequal inputs',function(){$p=preset('clocks');$p['reference']['rate']=2;rejects($p);});test('reject paired metric fixed comparator',function(){$p=preset('clocks');$p['reference_mode']='fixed';rejects($p);});test('reject categorical metric',function(){$p=preset('escape');$p['metric']=$p['reference_metric']='Continuous monotonicity criterion';rejects($p);});echo "$ok passed, $bad failed\n";exit($bad?1:0);
